insert into public.exercises (owner_id, slug, name, primary_muscles, secondary_muscles, equipment, mechanics, instructions) values (null, 'bankpress', 'Bänkpress', array['chest']::text[], array['triceps', 'shoulders']::text[], 'barbell', 'compound', array['Ligg på bänken med fötterna i golvet och skulderbladen indragna.', 'Greppa stången något bredare än axelbredd.', 'Sänk stången kontrollerat mot nedre delen av bröstet.', 'Pressa upp till raka armar utan att tappa spänningen i ryggen.']::text[]);
